static public class FnExpr extends ObjExpr{
	final static Type aFnType = Type.getType(AFunction.class);
	final static Type restFnType = Type.getType(RestFn.class);
	//if there is a variadic overload (there can only be one) it is stored here
	FnMethod variadicMethod = null;
	IPersistentCollection methods;
	private boolean hasPrimSigs;
	private boolean hasMeta;
    private boolean hasEnclosingMethod;
	//	String superName = null;
    Class jc;

	public FnExpr(Object tag){
		super(tag);
	}

	public boolean hasJavaClass() {
		return true;
	}

	boolean supportsMeta(){
		return hasMeta;
	}

	public Class getJavaClass() {
        if (jc == null)
            jc = tag != null ? HostExpr.tagToClass(tag) : AFunction.class;
        return jc;
	}

	protected void emitMethods(ClassVisitor cv){
		//override of invoke/doInvoke for each method
		for(ISeq s = RT.seq(methods); s != null; s = s.next())
			{
			ObjMethod method = (ObjMethod) s.first();
			method.emit(this, cv);
			}

		if(isVariadic())
			{
			GeneratorAdapter gen = new GeneratorAdapter(ACC_PUBLIC,
			                                            Method.getMethod("int getRequiredArity()"),
			                                            null,
			                                            null,
			                                            cv);
			gen.visitCode();
			gen.push(variadicMethod.reqParms.count());
			gen.returnValue();
			gen.endMethod();
			}
	}

	static Expr parse(C context, ISeq form, String name) {
		ISeq origForm = form;
		FnExpr fn = new FnExpr(tagOf(form));
		Keyword retkey = Keyword.intern(null, "rettag");
		Object rettag = RT.get(RT.meta(form), retkey);
		fn.src = form;
		ObjMethod enclosingMethod = (ObjMethod) METHOD.deref();
        fn.hasEnclosingMethod = enclosingMethod != null;
		if(((IMeta) form.first()).meta() != null)
			{
			fn.onceOnly = RT.booleanCast(RT.get(RT.meta(form.first()), Keyword.intern(null, "once")));
//			fn.superName = (String) RT.get(RT.meta(form.first()), Keyword.intern(null, "super-name"));
			}
		//fn.thisName = name;

		String basename = (enclosingMethod != null ?
		                  enclosingMethod.objx.name
		                  : (munge(currentNS().name.name))) + "$";

		Symbol nm = null;

		if(RT.second(form) instanceof Symbol) {
			nm = (Symbol) RT.second(form);
			name = nm.name + "__" + RT.nextID();
		} else {
			if(name == null)
				name = "fn__" + RT.nextID();
			else if (enclosingMethod != null)
				name += "__" + RT.nextID();
		}

		String simpleName = munge(name).replace(".", "_DOT_");

		fn.name = basename + simpleName;
		fn.internalName = fn.name.replace('.', '/');
		fn.objtype = Type.getObjectType(fn.internalName);
		ArrayList<String> prims = new ArrayList();
		try
			{
			Var.pushThreadBindings(
					RT.mapUniqueKeys(CONSTANTS, PersistentVector.EMPTY,
					       CONSTANT_IDS, new IdentityHashMap(),
					       KEYWORDS, PersistentHashMap.EMPTY,
					       VARS, PersistentHashMap.EMPTY,
					       KEYWORD_CALLSITES, PersistentVector.EMPTY,
					       PROTOCOL_CALLSITES, PersistentVector.EMPTY,
					       VAR_CALLSITES, emptyVarCallSites(),
                                               NO_RECUR, null
					));

			//arglist might be preceded by symbol naming this fn
			if(nm != null)
				{
				fn.thisName = nm.name;
				form = RT.cons(FN, RT.next(RT.next(form)));
				}

			//now (fn [args] body...) or (fn ([args] body...) ([args2] body2...) ...)
			//turn former into latter
			if(RT.second(form) instanceof IPersistentVector)
				form = RT.list(FN, RT.next(form));
			fn.line = lineDeref();
			fn.column = columnDeref();
			FnMethod[] methodArray = new FnMethod[MAX_POSITIONAL_ARITY + 1];
			FnMethod variadicMethod = null;
			boolean usesThis = false;
			for(ISeq s = RT.next(form); s != null; s = RT.next(s))
				{
				FnMethod f = FnMethod.parse(fn, (ISeq) RT.first(s), rettag);
				if(f.usesThis)
					{
//					System.out.println(fn.name + " use this");
					usesThis = true;
					}
				if(f.isVariadic())
					{
					if(variadicMethod == null)
						variadicMethod = f;
					else
						throw Util.runtimeException("Can't have more than 1 variadic overload");
					}
				else if(methodArray[f.reqParms.count()] == null)
					methodArray[f.reqParms.count()] = f;
				else
					throw Util.runtimeException("Can't have 2 overloads with same arity");
				if(f.prim != null)
					prims.add(f.prim);
				}
			if(variadicMethod != null)
				{
				for(int i = variadicMethod.reqParms.count() + 1; i <= MAX_POSITIONAL_ARITY; i++)
					if(methodArray[i] != null)
						throw Util.runtimeException(
								"Can't have fixed arity function with more params than variadic function");
				}

			fn.canBeDirect = !fn.hasEnclosingMethod && fn.closes.count() == 0 && !usesThis;

			IPersistentCollection methods = null;
			for(int i = 0; i < methodArray.length; i++)
				if(methodArray[i] != null)
					methods = RT.conj(methods, methodArray[i]);
			if(variadicMethod != null)
				methods = RT.conj(methods, variadicMethod);

			if(fn.canBeDirect){
				for(FnMethod fm : (Collection<FnMethod>)methods)
					{
					if(fm.locals != null)
						{
						for(LocalBinding lb : (Collection<LocalBinding>)RT.keys(fm.locals))
							{
							if(lb.isArg)
								lb.idx -= 1;
							}
						}
					}
				}

			fn.methods = methods;
			fn.variadicMethod = variadicMethod;
			fn.keywords = (IPersistentMap) KEYWORDS.deref();
			fn.vars = (IPersistentMap) VARS.deref();
			fn.constants = (PersistentVector) CONSTANTS.deref();
			fn.keywordCallsites = (IPersistentVector) KEYWORD_CALLSITES.deref();
			fn.protocolCallsites = (IPersistentVector) PROTOCOL_CALLSITES.deref();
			fn.varCallsites = (IPersistentSet) VAR_CALLSITES.deref();

			fn.constantsID = RT.nextID();
//			DynamicClassLoader loader = (DynamicClassLoader) LOADER.get();
//			loader.registerConstants(fn.constantsID, fn.constants.toArray());
			}
		finally
			{
			Var.popThreadBindings();
			}
		fn.hasPrimSigs = prims.size() > 0;
		IPersistentMap fmeta = RT.meta(origForm);
		if(fmeta != null)
			fmeta = fmeta.without(RT.LINE_KEY).without(RT.COLUMN_KEY).without(RT.FILE_KEY).without(retkey);

		fn.hasMeta = RT.count(fmeta) > 0;

		try
			{
			fn.compile(fn.isVariadic() ? "clojure/lang/RestFn" : "clojure/lang/AFunction",
			           (prims.size() == 0)?
			            null
						:prims.toArray(new String[prims.size()]),
			            fn.onceOnly);
			}
		catch(IOException e)
			{
			throw Util.sneakyThrow(e);
			}
		fn.getCompiledClass();

		if(fn.supportsMeta())
			{
			//System.err.println(name + " supports meta");
			return new MetaExpr(fn, MapExpr
					.parse(context == C.EVAL ? context : C.EXPRESSION, fmeta));
			}
		else
			return fn;
	}

	public final ObjMethod variadicMethod(){
		return variadicMethod;
	}

	boolean isVariadic(){
		return variadicMethod != null;
	}

	public final IPersistentCollection methods(){
		return methods;
	}

	public void emitForDefn(ObjExpr objx, GeneratorAdapter gen){
//		if(!hasPrimSigs && closes.count() == 0)
//			{
//			Type thunkType = Type.getType(FnLoaderThunk.class);
////			presumes var on stack
//			gen.dup();
//			gen.newInstance(thunkType);
//			gen.dupX1();
//			gen.swap();
//			gen.push(internalName.replace('/','.'));
//			gen.invokeConstructor(thunkType,Method.getMethod("void <init>(clojure.lang.Var,String)"));
//			}
//		else
			emit(C.EXPRESSION,objx,gen);
	}
}

static public class MethodValueExpr extends FnExpr
{
	private final List<Class> declaredSignature;
	private final Symbol targetSymbol;
	Class klass;
	Executable target;

	static HashMap<Class, Symbol> coerceFns = new HashMap<Class, Symbol>() {{
		put(double.class, Symbol.intern("double"));
		put(double[].class, Symbol.intern("doubles"));
		put(long.class, Symbol.intern("long"));
		put(long[].class, Symbol.intern("longs"));
		put(int.class, Symbol.intern("int"));
		put(int[].class, Symbol.intern("ints"));
		put(float.class, Symbol.intern("float"));
		put(float[].class, Symbol.intern("floats"));
		put(char.class, Symbol.intern("char"));
		put(char[].class, Symbol.intern("chars"));
		put(short.class, Symbol.intern("short"));
		put(short[].class, Symbol.intern("shorts"));
		put(byte.class, Symbol.intern("byte"));
		put(byte[].class, Symbol.intern("bytes"));
		put(boolean.class, Symbol.intern("boolean"));
		put(boolean[].class, Symbol.intern("booleans"));
	}};

	public MethodValueExpr(Object tag, Class c, Symbol targetSymbol, IPersistentVector sig)
	{
		super(tag);
		this.klass = c;
		this.declaredSignature = Reflector.processDeclaredSignature(sig);
		this.targetSymbol = targetSymbol;

		if (isCtor())
			this.target = Reflector.findMatchingTarget(c.getConstructors(), c, this.klass.getName(), sig);
		else
			this.target = Reflector.findMatchingTarget(c.getMethods(), c, targetSymbol.name, sig);
	}

	public boolean isStatic() {
		return Modifier.isStatic(target.getModifiers());
	}

	public boolean isCtor() {
		return targetSymbol.name.endsWith(".");
	}

	public Object eval(){
		String name = buildThunkName();
		ISeq form = buildThunk(name);
		Expr retExpr = analyzeSeq(null, form, name);
		return retExpr.eval();
	}

	public void emit(C context, ObjExpr objx, GeneratorAdapter gen){
		String name = buildThunkName();
		ISeq form = buildThunk(name);
		Expr retExpr = analyzeSeq(context, form, name);
		retExpr.emit(context, objx, gen);
	}

	private String buildThunkName(){
		return "dot__" + targetSymbol + RT.nextID();
	}

	private ISeq buildThunk(String name) {
		// (fn dot__new42 ([^T arg] (new Klass arg)))
		// (fn dot__staticMethod42 (^r [^T arg] (. Klass staticMethod arg)))
		// (fn dot__instanceMethod42 (^r [^Klass self ^T arg] (. ^Klass self instanceMethod arg)))
		return	RT.list(Symbol.intern("fn"), Symbol.intern(name),
				buildThunkBody(buildThunkParams()));
	}

	private IPersistentVector buildThunkParams(){
		IPersistentVector params = PersistentVector.EMPTY;

		if(isCtor() || isStatic())
		{
			// [^T arg1 ^U arg2]
			for(Class klass : target.getParameterTypes())
			{
				params = params.cons(maybeHintParam(klass, Symbol.intern("arg" + RT.nextID())));
			}
		}
		else
		{
			// [^T self ^U arg]
			params = params.cons(Symbol.intern("self" + RT.nextID())
					.withMeta(PersistentHashMap.create(Keyword.intern("tag"), Symbol.intern(klass.getName()))));
			for(Class klass : target.getParameterTypes())
			{
				params = params.cons(maybeHintParam(klass, Symbol.intern("arg" + RT.nextID())));
			}
		}
		return maybeHintReturn((PersistentVector)params);
	}

	private IPersistentVector maybeHintReturn(PersistentVector params){
		// ^long [...]
		// ^double [...]
		if (!isCtor())
		{
			Class t = ((java.lang.reflect.Method) target).getReturnType();

			if (t.isPrimitive() && (t.equals(Long.TYPE) || t.equals(Double.TYPE)))
			{
				return params.withMeta(PersistentHashMap.create(Keyword.intern("tag"), coerceFns.get(t)));
			}
		}
		return params;
	}

	private Symbol maybeHintParam(Class klass, Symbol name){
		if (klass.equals(Long.TYPE) || klass.equals(Double.TYPE) || !klass.isPrimitive())
		{
			return (Symbol) name.withMeta(PersistentHashMap.create(Keyword.intern("tag"), Symbol.intern(klass.getName())));
		}
		return name;
	}

	private ISeq buildThunkBody(IPersistentVector params){
		// ([^T arg] (. Klass staticMethod arg))
		// ([^Klass self ^T arg] (. self instanceMethod arg))
		// ([^T arg] (new Klass arg))
		ISeq body = RT.list(params, buildThunkDispatch(params));
		return body;
	}

	ISeq maybeCoerceArgs(ISeq args){
		Class[] sig = target.getParameterTypes();
		ArrayList ret = new ArrayList();

		for(int i = 0; args != null; args = args.next(), i++)
		{
			if (coerceFns.containsKey(sig[i]))
			{
				ArrayList coerceCall = new ArrayList();
				coerceCall.add(coerceFns.get(sig[i]));
				coerceCall.add(args.first());
				ret.add(RT.seq(coerceCall));
			}
			else
			{
				ret.add(args.first());
			}
		}

		return RT.seq(ret);
	}

	private ISeq buildThunkDispatch(IPersistentVector params){
		if (isCtor())
		{
			// ([^T arg] (new Klass arg))
			// ([^long arg1 ^double arg2] (new Klass arg1 arg2))
			// ([prim] (new Klass (coercefn prim)))
			return RT.listStar(Symbol.intern("new"), Symbol.intern(klass.getName()), maybeCoerceArgs(params.seq()));
		}
		else if (isStatic())
		{
			// ([^T arg] (. Klass staticMethod arg))
			// ([^long arg1 ^double arg2] (. Klass staticMethod arg1 arg2))
			// ([prim] (. Klass staticMethod (coercefn prim)))
			return RT.listStar(Symbol.intern("."),
					Symbol.intern(klass.getName()), Symbol.intern(target.getName()),
					maybeCoerceArgs(params.seq()));
		}
		else
		{
			// ([^Klass self ^T arg] (. self instanceMethod arg))
			// ([^long arg1 ^double arg2] (. self instanceMethod arg1 arg2))
			// ([^Klass self prim] (. self instanceMethod (coercefn prim)))
			return RT.listStar(Symbol.intern("."),
					params.seq().first(), Symbol.intern(target.getName()),
					maybeCoerceArgs(params.seq().next()));
		}
	}

	public boolean hasJavaClass() {
		return true;
	}

	public Class getJavaClass() {
		if (isCtor())
		{
			return this.klass;
		}
		else {
			return ((java.lang.reflect.Method)this.target).getReturnType();
		}
	}
}


static public class ObjExpr implements Expr{
	static final String CONST_PREFIX = "const__";
	String name;
