        Matches<HighlightsMatch> matcher = monitor.match(buildDoc("doc1", "this is a test document"),
                HighlightingMatcher.FACTORY);

        assertThat(matcher)
                .hasMatchCount("doc1", 1)
                .matchesQuery("query1", "doc1")
                    .inField(textfield)
                        .withHit(new HighlightsMatch.Hit(3, 10, 3, 14));

