        match.addHit("field", 0, 1, -1, -1);
        match.addHit("afield", 0, 1, 0, 4);

        Assertions.assertThat(match.toString())
                .isEqualTo("Match(doc=1,query=1){hits={afield=[0(0)->1(4)], field=[0(-1)->1(-1), 2(-1)->3(-1)]}}");

