    public class FlushAwareWriter extends StringWriter {

        private List<String> buffers = new ArrayList<>();

        @Override
        public void flush() {
            buffers.add(this.getBuffer().toString());
            super.flush();
        }

        public List<String> getFlushedBuffers() {
